## 3. Result-Generation Logic (form data → recommendation)

The core recommendation logic is defined INLINE in the Compass page (there is no separate logic lib for this module). The generic PDF helper follows.

Source: `client/src/pages/GenderAffirmingUroCompass.tsx`

```typescript
type GenderIdentity = "trans_woman" | "trans_man" | "non_binary" | "other";
type UrologicProcedure = "vaginoplasty" | "phalloplasty" | "metoidioplasty" | "orchiectomy" | "hysterectomy_oophorectomy" | "urethroplasty" | "scrotoplasty" | "other";

interface GAUInputs {
  genderIdentity: GenderIdentity;
  proposedProcedure: UrologicProcedure;
  patientAge: number;
  diagnosisGenderDysphoria: boolean;
  persistentDysphoria: boolean;
  durationMonths: number;
  mentalHealthEvaluation: boolean;
  mentalHealthClearance: boolean;
  hormoneTherapyMonths: number;
  hormoneTherapyContraindicated: boolean;
  realLifeExperienceMonths: number;
  comorbidMentalHealthTreated: boolean;
  informedConsent: boolean;
  twoLettersObtained: boolean;
}

const defaultInputs: GAUInputs = {
  genderIdentity: "trans_woman", proposedProcedure: "vaginoplasty", patientAge: 0,
  diagnosisGenderDysphoria: false, persistentDysphoria: false, durationMonths: 0,
  mentalHealthEvaluation: false, mentalHealthClearance: false, hormoneTherapyMonths: 0,
  hormoneTherapyContraindicated: false, realLifeExperienceMonths: 0,
  comorbidMentalHealthTreated: true, informedConsent: false, twoLettersObtained: false,
};

function evaluate(inputs: GAUInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Coleman E, et al. Standards of Care for the Health of Transgender and Gender Diverse People, Version 8. Int J Transgend Health. 2022;23(Suppl 1):S1-S259.",
    "WPATH SOC-8: Chapter 12 — Surgical and Postoperative Care. Int J Transgend Health. 2022.",
    "American Urological Association. Policy Statement: Transgender and Gender-Diverse Health Care. 2021.",
    "Raffaini M, et al. Gender-affirming surgery: a systematic review of outcomes. J Plast Reconstr Aesthet Surg. 2021.",
    "Deutsch MB, ed. Guidelines for the Primary and Gender-Affirming Care of Transgender and Gender Nonbinary People. UCSF, 2016.",
  ];

  const metCriteria: string[] = [];
  const missingCriteria: string[] = [];

  // WPATH SOC-8 criteria assessment
  if (inputs.diagnosisGenderDysphoria) metCriteria.push("Gender dysphoria diagnosis documented");
  else missingCriteria.push("Gender dysphoria diagnosis required (DSM-5 F64.0 or ICD-11 HA60)");

  if (inputs.persistentDysphoria && inputs.durationMonths >= 6) metCriteria.push(`Persistent gender dysphoria for ${inputs.durationMonths} months`);
  else missingCriteria.push("Persistent, well-documented gender dysphoria required");

  if (inputs.mentalHealthEvaluation && inputs.mentalHealthClearance) metCriteria.push("Mental health evaluation with surgical clearance obtained");
  else missingCriteria.push("Mental health evaluation and clearance required");

  if (inputs.comorbidMentalHealthTreated) metCriteria.push("Comorbid mental health conditions treated/stable");
  else missingCriteria.push("Comorbid mental health conditions must be stable before surgery");

  if (inputs.informedConsent) metCriteria.push("Informed consent documented");
  else missingCriteria.push("Informed consent process required");

  // Hormone therapy requirement (procedure-specific)
  const requiresHormones = ["vaginoplasty", "phalloplasty", "metoidioplasty"].includes(inputs.proposedProcedure);
  if (requiresHormones) {
    if (inputs.hormoneTherapyContraindicated) {
      metCriteria.push("Hormone therapy contraindicated — documented exception");
    } else if (inputs.hormoneTherapyMonths >= 12) {
      metCriteria.push(`${inputs.hormoneTherapyMonths} months of hormone therapy completed`);
    } else {
      missingCriteria.push("≥12 months of hormone therapy required before genital surgery (WPATH SOC-8)");
    }
  }

  // Age
  if (inputs.patientAge < 18) {
    warnings.push("Patient is a minor: additional criteria apply per WPATH SOC-8 Chapter 6 (Adolescents). Parental consent and multidisciplinary team required.");
  }

  const allMet = missingCriteria.length === 0;
  const recommendation = allMet ? "indicated" : "not_yet_indicated";
  const procedure = inputs.proposedProcedure.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());

  rationale.push("WPATH SOC-8 (2022) provides the current standard of care for gender-affirming surgical procedures.");
  rationale.push("AUA Policy Statement (2021) supports access to gender-affirming urologic care as medically necessary.");

  if (inputs.twoLettersObtained) {
    rationale.push("Two letters of support from qualified mental health professionals obtained — meets most payer requirements.");
  } else {
    warnings.push("Most payers require 2 letters of support from qualified mental health professionals (WPATH SOC-7 legacy requirement still used by many insurers).");
  }

  return { recommendation, procedure, metCriteria, missingCriteria, warnings, rationale, references };
}
